// Reinsert all elements from old table into new table
for (size_t i = 0; i < aTab->size; i++) {
    if (aTab->table[i] != nullptr) {
        // Insert each element into the new table
        for (auto& element : *aTab->table[i]) {
            // Calculate the hash value for the element
            size_t hash = std::hash<std::string>{}(element.key) % ckh->size;

            // Insert the element into the new table
            if (ckh->table[hash] == nullptr) {
                ckh->table[hash] = new std::vector<std::pair<std::string, std::string>>();
            }
            ckh->table[hash]->push_back(element);
        }
    }
}

